CREATE OR REPLACE FUNCTION public.fn_create_event(p_id uuid, p_tenant_id uuid, p_title character varying, p_description text, p_event_type_id uuid, p_event_date date, p_start_time time without time zone, p_end_time time without time zone, p_location character varying, p_organizer_id uuid, p_status character varying, p_scope character varying, p_branch_id uuid, p_is_organization_wide boolean, p_photo_urls text[], p_created_at timestamp with time zone, p_updated_at timestamp with time zone)  RETURNS uuid  LANGUAGE plpgsql AS $function$ BEGIN     INSERT INTO events (         id, tenant_id, title, description, event_type_id, event_date, start_time, end_time,         location, organizer_id, status, scope, branch_id, is_organization_wide, photo_urls, created_at, updated_at     )     VALUES (         p_id, p_tenant_id, p_title, p_description, p_event_type_id, p_event_date, p_start_time, p_end_time,         p_location, p_organizer_id, p_status, p_scope, p_branch_id, p_is_organization_wide, p_photo_urls, p_created_at, p_updated_at     );     RETURN p_id; END; $function$ ;
